 a: string;        // author name\n  r: string;        // role\n  company?: string | null; // company or location (optional, shown as secondary line)\n  stars: number;    // 1\u20135\n}\n\nexport interface FaqItem {\n  q: string;\n  a: string;\n}\n\nexport interface FooterCol {\n  h: string;           // column heading\n  links: FooterLink[]; // v2.1: was string[]\n}\n\nexport interface HeroContent {\n  eyebrow: string;\n  headline: string;\n  headlineEmphasis: string | null; // substring of headline to render in accent color; null \u2192 no highlight\n  sub: string;\n  formLabel: string;\n  placeholder: string;\n  cta: string;\n  secondaryCta: string;            // ghost link below form\n  trust: string;\n  badge: string | null;            // null \u2192 omit hero badge\n  frictionReducers: string[];      // bullets under form; empty \u2192 omit\n  heroBullets: Array<{ value: string; label: string }>;\n}\n\nexport interface AboutContent {\n  eyebrow: string;\n  title: string;\n  body: string;\n  pillars: Pillar[];\n  stats: Stat[];\n}\n\nexport interface ServicesContent {\n  eyebrow: string;\n  title: string;\n  sub: string;\n  items: ServiceItem[];\n}\n\nexport interface WorkContent {\n  eyebrow: string;\n  title: string;\n  sub: string;\n  projects: Project[];\n  hidden: boolean; // true \u2192 hide section entirely\n}\n\nexport interface TestimonialsContent {\n  eyebrow: string;\n  title: string;\n  items: Testimonial[];\n}\n\nexport interface FaqContent {\n  eyebrow: string;\n  title: string;\n  sub: string;     // explanatory line under title\n  items: FaqItem[];\n}\n\nexport interface FinalCtaContent {\n  eyebrow: string;\n  headline: string;\n  sub: string;\n  cta: string;\n  secondary: string | null; // null \u2192 omit \"Or call\u2026\" line\n  frictionReducers: string[];\n}\n\nexport interface FooterContent {\n  blurb: string;\n  cols: FooterCol[];\n  social: FooterLink[];    // v2.1: was string[]\n  legalLinks: FooterLink[];\n  legal: string;\n}\n\nexport interface BrandPalette {\n  accent:    string;\n  accentFg?: string;   // text drawn on accent bg \u2014 defaults to \"#ffffff\"\n  bg:        string;\n  bgSoft:    string;\n  ink:       string;\n  inkSoft:   string;\n  rule:      string;\n}\n\nexport interface BrandTypography {\n  fontSans:           string;\n  fontHeading:        string;\n  headingWeight:      number;\n  bodyWeight:         number;\n  headingTracking?:   string;\n  headingLineHeight?: number;\n}\n\nexport interface BrandContent {\n  name:        string;\n  short:       string;\n  long:        string;\n  established: string | null;\n  tagline:     string;\n  phone:       string;\n  phoneHref:   string;\n  email:       string;\n  address:     string;\n  license:     string | null;\n  palette:     BrandPalette;\n  typography:  BrandTypography;\n}\n\nexport interface ElementStyle {\n  color?: string;      // hex\n  fontSize?: number;   // px\n  fontWeight?: number; // 300\u2013800\n}\n\nexport interface SeoContent {\n  title: string;\n  description: string;\n  canonical: string;\n  googleAnalyticsId: string | null;\n  facebookPixelId: string | null;\n}\n\nexport interface ExtensionsContent {\n  trustBadges: string[] | null;\n  reviewBadge: {\n    rating: number;\n    count: number;\n    url: string;\n  } | null;\n  contactDetails: {\n    address: string;\n    mapsUrl: string | null;\n  } | null;\n  hours: Record<string, string> | null;\n  bookingUrl: string | null;\n  portalUrl: string | null;\n  agentName?: string | null;\n  serviceArea?: string[] | null;\n}\n\nexport interface SiteImages {\n  hero:         { portrait?: string; slides?: Array<{ url: string; alt: string }> };\n  about:        { feature?: string };\n  testimonials: { avatars?: string[] };\n  footer:       { logoImage?: string };\n}\n\nexport interface ContentMeta {\n  schema_version: string;\n  generated_at: string;\n  variation: \"D\";\n  is_placeholder: boolean;\n  missing_fields: string[];\n  placeholder_images?: string[];\n  selectedPlan: \"starter\" | \"growth\" | \"enterprise\";\n  siteIndex?: number;\n  siteCount?: number;\n  siblingSlugs?: string[];\n  formMode?: \"basic\" | \"detailed\";\n  scrapeExistingWebsite?: boolean;\n  scrapeWebsiteDomain?: string;\n  brandDirection?: {\n    differentiators: string;\n    targetCustomer: string;\n    vibe: string[];\n    tone: string[];\n    adjectives: string[];\n    references: string;\n    forbidden: string;\n  };\n  industry?: string;\n}\n\nexport interface SiteContent {\n  brand:        BrandContent;\n  nav:          NavItem[];\n  announcement: string | null;\n  trust:        { label: string; logos: string[] };\n  hero:         HeroContent;\n  about:        AboutContent;\n  services:     ServicesContent;\n  work:         WorkContent;\n  testimonials: TestimonialsContent;\n  faq:          FaqContent;\n  finalCta:     FinalCtaContent;\n  footer:       FooterContent;\n  seo:          SeoContent;\n  extensions:   ExtensionsContent;\n  images:       SiteImages;\n  _meta:        ContentMeta;\n  overrides?:   Record<string, unknown>;\n}\n\n/** @deprecated Use BrandContent */\nexport type Brand = BrandContent;\n";
